"""Tests for slugify function."""
import pytest
from slugkit import slugify


class TestBasicSlugForm:
    """Tests for basic slug form requirement."""

    @pytest.mark.l4("C-540dbbf7")
    def test_words_are_lowercased_and_hyphenated(self):
        assert slugify("Hello World") == "hello-world"

    @pytest.mark.l4("C-968f19f6")
    def test_runs_of_separators_collapse(self):
        assert slugify("  Hello,   World!! ") == "hello-world"

    @pytest.mark.l4("C-dc5ae7cf")
    def test_empty_input_raises_value_error(self):
        with pytest.raises(ValueError):
            slugify("")
        with pytest.raises(ValueError):
            slugify("!!!")


class TestUnicodeTransliteration:
    """Tests for unicode transliteration requirement."""

    @pytest.mark.l4("C-2d8e9905")
    def test_accents_are_transliterated(self):
        assert slugify("Crème Brûlée") == "creme-brulee"

    @pytest.mark.l4("C-c5654742")
    def test_non_latin_characters_are_dropped(self):
        assert slugify("Café 東京") == "cafe"

