class TestMaximumLength:
    """Tests for maximum length requirement."""

    @pytest.mark.l4("C-31395b1a")
    def test_long_input_is_truncated_to_max_length(self):
        result = slugify("a" * 100)
        assert len(result) == 64
        assert result == "a" * 64

    @pytest.mark.l4("C-646c6823")
    def test_no_trailing_hyphen_after_truncation(self):
        result = slugify("hello world", max_length=6)
        assert result == "hello"
        assert not result.endswith("-")

